//! Watches the folder and debounces events.
use std::time::Duration;

pub const DEBOUNCE_MS: u64 = 200;

pub struct WatchContext {
    pub generation: u64,
}

impl WatchContext {
    pub fn handle(&self, batch: Vec<Event>) {
        self.reindex(batch);
    }
}

//! The single door to every AI provider.
pub struct AiGateway {
    running: Slot,
}

impl AiGateway {
    pub fn start(&self, action: UserAction) -> u32 {
        let id = self.next_id();
        self.running.set(id);
        id
    }

    pub fn cancel(&self, id: u32) {
        self.running.stop(id);
    }
}
